def repair_zero_assignment_amounts(apps, schema_editor):
    """Fix assignments created before fee items calculated the total.

    The post-save signal creates assignments as soon as the fee structure is
    saved, but fee items are saved afterwards.  Old rows can therefore have a
    zero amount while the fee structure has a real total.  Only zero rows are
    touched so manual per-student overrides are preserved.
    """
    StudentFeeAssignment = apps.get_model("fees", "StudentFeeAssignment")
    stale = list(
        StudentFeeAssignment.objects.filter(amount=Decimal("0.00"))
        .select_related("fee_structure")
    )
    for assignment in stale:
        fee_amount = assignment.fee_structure.amount
        if fee_amount and fee_amount > Decimal("0.00"):
            assignment.amount = fee_amount

    if stale:
        StudentFeeAssignment.objects.bulk_update(stale, ["amount"])


